pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(
        uint64 number_,
        uint64 timestamp_,
        uint256 basefee_,
        bytes32 hash_,
        uint64 seq_,
        bytes32 batcher_,
        uint256 overhead_,
        uint256 scalar_,
        address actor
    ) public {
        vm.assume(actor != address(0));
        // The rule: setL1BlockValues must never mutate state — c.basefee() stays 0.
        // To make the call succeed (so the mutant's assignment executes), make actor
        // match the depositor account expected by the contract.
        address depositor = c.depositorAccount();
        if (actor != depositor) {
            // For non-depositors both versions revert; skip to keep rule on success path.
            vm.prank(actor);
            try c.setL1BlockValues(number_, timestamp_, basefee_, hash_, seq_, batcher_, overhead_, scalar_) {
                revert("unexpected success");
            } catch {
                return;
            }
        }
        vm.prank(depositor);
        c.setL1BlockValues(number_, timestamp_, basefee_, hash_, seq_, batcher_, overhead_, scalar_);
        assertTrue(c.basefee() == 0, "setL1BlockValues must not mutate basefee");
    }
}

