pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(
        uint64 _number,
        uint64 _timestamp,
        uint256 _basefee,
        bytes32 _hash,
        uint64 _sequenceNumber,
        bytes32 _batcherHash,
        uint256 _l1FeeOverhead,
        uint256 _l1FeeScalar
    ) public {
        // The depositor account is the zero address, so prank as address(0);
        // the require passes in both versions, isolating the mutation.
        vm.prank(address(0));
        c.setL1BlockValues(
            _number,
            _timestamp,
            _basefee,
            _hash,
            _sequenceNumber,
            _batcherHash,
            _l1FeeOverhead,
            _l1FeeScalar
        );
        assertTrue(
            c.number() == 0 &&
            c.timestamp() == 0 &&
            c.basefee() == 0 &&
            c.hash() == bytes32(0) &&
            c.sequenceNumber() == 0 &&
            c.batcherHash() == bytes32(0) &&
            c.l1FeeOverhead() == 0 &&
            c.l1FeeScalar() == 0
        );
    }
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function runTest(uint64 n, uint64 t, uint256 f, bytes32 h, uint64 s, bytes32 b, uint256 o, uint256 sc) external {
        require(c.depositorAccount() != address(this), "must be non-depositor");
        bool ok;
        (ok, ) = address(c).call(
            abi.encodeWithSelector(
                c.setL1BlockValues.selector,
                n, t, f, h, s, b, o, sc
            )
        );
        assert(!ok);
    }

    receive() external payable {}
    fallback() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function runTest(
        uint64 n,
        uint64 t,
        uint256 f,
        bytes32 h,
        uint64 s,
        bytes32 b,
        uint256 o,
        uint256 sc
    ) external {
        bool reverted = false;
        // state-changing call as its own top-level statement inside try/catch is forbidden,
        // so use low-level style via try is not allowed; instead detect revert via return data trick:
        // We call through c using a try wrapper is disallowed; use low-level call on address(c).
        (bool ok, ) = address(c).call(
            abi.encodeWithSignature(
                "setL1BlockValues(uint64,uint64,uint256,bytes32,uint64,bytes32,uint256,uint256)",
                n, t, f, h, s, b, o, sc
            )
        );
        reverted = !ok;
        assert(reverted);
    }

    receive() external payable {}
    fallback() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint64 n, uint64 t, uint256 f, bytes32 h, uint64 s, bytes32 b, uint256 o, uint256 sc) public payable {
        bool reverted;
        try c.setL1BlockValues(n, t, f, h, s, b, o, sc) { reverted = false; } catch { reverted = true; }
        assert(reverted == (address(this) != c.depositorAccount()));
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(
        uint64 _number,
        uint64 _timestamp,
        uint256 _basefee,
        bytes32 _hash,
        uint64 _sequenceNumber,
        bytes32 _batcherHash,
        uint256 _l1FeeOverhead,
        uint256 _l1FeeScalar
    ) public payable {
        require(true);
        bool reverted;
        try c.setL1BlockValues(_number, _timestamp, _basefee, _hash, _sequenceNumber, _batcherHash, _l1FeeOverhead, _l1FeeScalar) { reverted = false; } catch { reverted = true; }
        assert(reverted);
    }
    receive() external payable {}
}
